referenceSolutions.javascript:
export function solve(operations) {
  const registry = new Map();
  return operations.map(([op, id, value]) => {
    if (op === "set") {
      registry.set(id, value);
      return null;
    }
    if (op === "delete") return registry.delete(id);
    return registry.has(id) ? registry.get(id) : null;
  });
}

